actions.script:
const L = (text) => ec.l10n.localize(text)
const fmt = (value) => value == null ? '' : ec.l10n.format(Math.round(Number(String(value)) * 10) / 10, '#,##0.#')
const options = ec.service.sync().name('ironstone.ReportServices.get#ReportOptions').call() || {}
ec.message.clearErrors()
projectOptions = Array.from(options.projectOptions || [])
typeOptions = Array.from(options.typeOptions || [])
groupOptions = [['status', 'Status'], ['type', 'Type'], ['assignee', 'Assignee'], ['priority', 'Priority'], ['component', 'Component'], ['project', 'Project']]
        .map(([value, label]) => ({value: value, label: L(label)}))
if (!groupBy) groupBy = 'status'
groupTitle = (groupOptions.find((one) => one.value === groupBy) || groupOptions[0]).label
const out = ec.service.sync().name('mantle.work.ProjectReportServices.get#WorkItemSummary').parameters({rootWorkEffortId: rootWorkEffortId || null,
    fromDate: fromDate || null, thruDate: thruDate || null, purposeEnumId: purposeEnumId || null, groupBy: groupBy}).call() || {}
ec.message.clearErrors()
fromDate = out.fromDay; thruDate = out.thruDay
const counts = out.counts || {open: 0, created: 0, resolved: 0, overdue: 0}
const totals = out.totals || {}
openValue = String(counts.open || 0); createdValue = String(counts.created || 0); resolvedValue = String(counts.resolved || 0); overdueValue = String(counts.overdue || 0)
cycleValue = totals.averageCycleDays == null ? '—' : fmt(totals.averageCycleDays) + ' ' + L('days')
const statuses = Array.from(out.statusList || [])
maxStatuses = 12
statusCount = Math.min(statuses.length, maxStatuses)
statusesCut = statuses.length > maxStatuses
statusTitles = []
for (let i = 0; i < maxStatuses; i++) statusTitles.push(i < statuses.length ? statuses[i].label : '')
const rowOf = (row, isTotal) => {
    const one = {isTotal: isTotal, groupLabel: row.groupLabel || '', total: row.total || 0, open: row.open || 0, overdue: row.overdue || 0, resolved: row.resolved || 0,
        cycleText: row.averageCycleDays == null ? '' : fmt(row.averageCycleDays)}
    const map = row.statusCounts || {}
    for (let i = 0; i < maxStatuses; i++) {
        const key = i < statuses.length ? (statuses[i].statusId || '') : null
        const count = key == null ? 0 : (map[key] || 0)
        one['s' + i] = count ? String(count) : ''
    }
    return one
}
summaryRows = Array.from(out.rowList || []).map((row) => rowOf(row, false))
anyFound = summaryRows.length > 0
if (anyFound) summaryRows.push(rowOf(Object.assign({}, totals, {groupLabel: L('Total')}), true))
summaryRowsCount = summaryRows.length
itemCountText = String(out.itemCount || 0)
rangeText = ec.l10n.format(ec.l10n.parseTimestamp(out.fromDay + ' 12:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS'), 'MMM d, yyyy') + ' – '
    + ec.l10n.format(ec.l10n.parseTimestamp(out.thruDay + ' 12:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS'), 'MMM d, yyyy')
// the charts: created against resolved by week, and the open items by status
const weeks = Array.from(out.weekList || [])
hasFlow = weeks.length > 0 && (counts.created > 0 || counts.resolved > 0)
const flow = hasFlow ? ec.service.sync().name('ironstone.ReportServices.get#ChartConfig').parameters({id: 'WorkItemFlowChart', type: 'bar',
    labels: weeks.map((week) => week.label), series: [{name: L('Created'), data: weeks.map((week) => week.created)},
        {name: L('Resolved'), data: weeks.map((week) => week.resolved)}], yTitle: L('Items')}).call() || {} : {}
ec.message.clearErrors()
flowHtml = flow.html || ''
flowTui = flow.tui || {t: 'text', text: ''}
const open = Array.from(out.openByStatus || [])
hasOpen = open.length > 0
const openChart = hasOpen ? ec.service.sync().name('ironstone.ReportServices.get#ChartConfig').parameters({id: 'WorkItemOpenChart', type: 'bar',
    labels: open.map((one) => one.label), series: [{name: L('Open items'), data: open.map((one) => one.count)}], horizontal: true,
    height: Math.max(160, 40 + open.length * 32) + 'px'}).call() || {} : {}
ec.message.clearErrors()
openHtml = openChart.html || ''
openTui = openChart.tui || {t: 'text', text: ''}
const query = {rootWorkEffortId: rootWorkEffortId || '', fromDate: out.fromDay, thruDate: out.thruDay, purposeEnumId: purposeEnumId || '', groupBy: groupBy}
printUrl = '/apps/Projects/Reports/WorkItems?renderMode=html-print&' + Object.entries(query).filter(([key, value]) => value).map(([key, value]) => key + '=' + encodeURIComponent(value)).join('&')
